import React from "react";
import { BarChart } from "tabler-react";
import "tabler-react/style.css";

export default function BarrasVerticales() {
  return <BarChart title="Peso por mes" height="300px" complete legend
    series={[[12, 18, 24], [10, 16, 20]]}
    seriesName={["Cartera", "Referencia"]}
    colors={["#3676c8", "#21a48a"]}
    xAxisData={["Ene", "Feb", "Mar"]} rotateX={0}
    yAxisFormatter={value => value + " %"}
    yAxisMinMax={(range, boundary) => boundary === "min" ? 0 : Math.ceil(range.max * 1.1)}
    tooltipFormatter={item => item.seriesName + ": " + item.value + " %"}
    download downloadName="peso-mensual" downloadTitle="Descargar imagen" />;
}

